  "chat.designToolbox.prompt.contextGeneric":
    "Current target: the currently open HTML / design file / web element.",
  "chat.designToolbox.prompt.contextSpecific":
    "Current target: {kind} · {label}.",
  "chat.designToolbox.prompt.preserveDraft":
    "Preserve the intent already in the composer: {draft}",
  "chat.designToolbox.prompt.selectedSkill":
    "Selected skill: {skill}. Use it as the primary workflow for this turn.",
  "chat.designToolbox.prompt.noSkill":
    "If no specific skill matched, first choose the best combination from available skills, MCP, plugins, connectors, and design files.",
  "chat.designToolbox.prompt.autoMatchIntro":
    "Act as the Creative Director orchestrator and complete a design workflow:",
  "chat.designToolbox.prompt.autoMatchStep1":
    "1. Define what “good-looking design” means first: audience, business goal, brand feel, style references, information density, color/type/motion/asset standards, and AI/template patterns to avoid.",
  "chat.designToolbox.prompt.autoMatchStep2":
    "2. Search and match the full resource index above. Do not only use design toolbox recommendations; combine skills, MCP, plugins, connectors, and design files when useful.",
  "chat.designToolbox.prompt.autoMatchStep3":
    "3. If the target or aesthetic bar is still unclear, guide me with a structured question-form, include recommended defaults, and make each finite-choice question editable with a custom answer field. If it is clear enough, execute the next step directly.",
  "chat.designToolbox.prompt.autoMatchStep4":
    "4. Complete the flow in this order: diagnose -> style direction -> resource selection -> concrete edit/generation -> verification. At each step, explain why these resources were chosen and what needs confirmation next.",
  "chat.designToolbox.prompt.assetSearch":
    "Find the best image/reference assets for the current design. Search available files, connectors, MCPs, browser captures, and generation tools. Return concrete candidates with usage notes, licensing/source caveats when relevant, and a fallback generation prompt if no usable asset exists.",
  "chat.designToolbox.prompt.iconWorkflow":
    "Improve the icon system for the current design: find missing icons, replace weak icons, keep stroke/fill/radius/weight consistent, prefer existing icon libraries when available, and generate SVG/icon prompts only when a library icon is insufficient.",
  "chat.designToolbox.prompt.imageReplace":
    "Audit every visible image slot in the current design, identify weak or placeholder imagery, then replace or specify better hero, section, background, card, and social images. Preserve layout and provide exact file/prompt/source choices.",
  "chat.designToolbox.prompt.referenceExtract":
    "Use the current reference image/site/design file as visual input. Extract palette, type scale, layout rhythm, component posture, motion cues, and asset style, then apply those findings to the current design without copying protected brand assets verbatim.",
  "chat.designToolbox.prompt.motion":
    "Add high-quality motion to the current HTML / page element: choose the most useful 1-2 entrance, scroll, state-transition, transition, Rive/Lottie-style icon motion, or GSAP/Motion micro-interaction moments. Keep it restrained, prefer transform / opacity, and include prefers-reduced-motion fallbacks.",
  "chat.designToolbox.prompt.planOutline":
    "Create or update a Markdown planning document for a PPT/deck outline from this idea. Do not generate the final deck yet. Include slide-by-slide titles, goals, content bullets, visual direction, required data/assets, and open questions. Save it as a `.md` file in Design Files and tell me which file to review.",
  "chat.designToolbox.prompt.motionPolish":
    "Review and polish existing motion timing, easing, performance, and accessibility. Remove abrupt, cheap, or readability-harming animation; use a more refined timeline when needed.",
  "chat.designToolbox.prompt.transitionMotion":
    "Design high-quality transitions for the current design: page/scene changes, loading bridges, state changes, and section handoffs. Use GSAP/Motion/CSS where appropriate, keep it performant, and include reduced-motion behavior.",
  "chat.designToolbox.prompt.threejsScene":
    "Plan or implement a focused Three.js/WebGL visual for the current design. Consider Three.js, Spline-style scenes, Vanta backgrounds, particle systems, Mapbox/deck.gl data layers, or browser portal effects, but keep the scene useful and verify it renders.",
  "chat.designToolbox.prompt.antiAiPolish":
    "Do one anti-AI-feel polish pass: remove templated layouts, cheap gradients/glows, meaningless card stacks, and vague copy. Preserve information and make it feel like a real designer delivered it.",
  "chat.designToolbox.prompt.visualPolish":
    "Polish this design until it is ready to ship: check hierarchy, typography, spacing, responsive behavior, button states, empty/loading/error states, and accessibility; directly fix the most important issues.",
  "chat.designToolbox.prompt.imageGen":
    "Create the next visual-asset plan for this design: section references, hero assets, illustrations, icons, social images, or a moodboard. First decide what kind of image is missing, then provide executable generation prompts / file plan.",
  "chat.designToolbox.prompt.chartGen":
    "Generate the right chart, diagram, or data-visualization for the current design. Choose between ECharts, React Flow, SVG/CSS diagrams, radar charts, relationship maps, dashboards, or deck.gl/map visualizations based on the data and user goal.",
  "chat.designToolbox.prompt.logoGen":
    "Create logo and identity directions for the current brand. Produce multiple routes for wordmark, symbol, lockup, palette, usage rules, and generation prompts; make sure the result is original and usable in the current artifact.",
  "chat.designToolbox.prompt.videoGen":
    "Turn this design toward video: create a short-video storyboard, Hyperframes / Remotion frame structure, or Sora/fal-ready prompt. Prefer making the existing HTML / page content naturally become shots.",
  "chat.designToolbox.prompt.useSkill": "Use {skill} on the current design.",
  "chat.designToolbox.prompt.skillInstruction":
    "First decide the best follow-up goal, then complete one concrete pass. If it depends on external assets or APIs, provide a runnable fallback or state what I need to provide.",
  "chat.designToolbox.prompt.selectedResource":
    "Selected resource: {kind} · {title} ({id}).",
  "chat.designToolbox.prompt.resourceDescription":
    "Resource description: {description}",
  "chat.designToolbox.prompt.pluginResource":
    "Use this plugin as the main context for the current design flow. If it exposes inputs or GenUI, guide me to choose when needed; if it does not fit the target, choose a better global resource and explain why.",
  "chat.designToolbox.prompt.mcpResource":
    "Prefer this MCP capability for the next design step. When external assets, web capture, image/video generation, or data are needed, first decide whether it can do the job, then give an executable plan.",
  "chat.designToolbox.prompt.mcpTemplateResource":
    "This MCP is a configurable template. If it is the most useful tool for this design step, guide setup first; if a configured alternative exists, continue with that alternative.",
  "chat.designToolbox.prompt.connectorResource":
    "Use this connector when real data, assets, account content, or external workflow access is needed. Before using it, explain what will be read or written and ask for confirmation when appropriate.",
  "chat.designToolbox.prompt.fileResource":
    "Use this design file as the current design target or reference asset and complete the next step from it. If other files need comparison, continue searching across all design files.",
  "chat.designToolbox.prompt.resourceIndex":
    "Global resource index: skills({skills}), plugins({plugins}), MCP({mcpEnabled} enabled / {mcpTemplates} templates), connectors({connectors} connected), design files({files}).",
