  "chat.example1Title": "Investor pitch deck",
  "chat.example1Tag": "Deck",
  "chat.example1Prompt":
    "Create a 10-slide investor pitch deck for an AI design tool — cover, problem, solution, product demo, market, traction, business model, team, ask, and contact. Swiss grid layout, oversized serif headlines, restrained charts; I will fine-tune each slide on the canvas afterwards.",
  "chat.example2Title": "SaaS landing prototype",
  "chat.example2Tag": "Prototype",
  "chat.example2Prompt":
    "Design a clickable landing-page prototype for an AI meeting-notes app — hero value proposition, product preview, three feature stories, testimonials, pricing table, FAQ, and CTA. Define a small design system first (palette, type scale, spacing) and keep every section on it.",
  "chat.example3Title": "Brand visual kit",
  "chat.example3Tag": "Brand",
  "chat.example3Prompt":
    "Build a starter brand kit for a specialty coffee brand — begin with three mood-board directions (palette, type pairing, texture references) laid out on the canvas; once I pick one, expand into logo explorations, a key-visual poster, and social covers, then compile a one-page brand guideline.",

