  "designFiles.documentTemplate.goalHeading": "Goal",
  "designFiles.documentTemplate.goalBody":
    "Describe what 安全设计工作台 should generate, edit, or decide from this document.",
  "designFiles.documentTemplate.capabilitiesHeading":
    "How to use this document",
  "designFiles.documentTemplate.capabilityMarkdown":
    "Use any Markdown format: headings, tables, checklists, links, quotes, code blocks, and images.",
  "designFiles.documentTemplate.capabilityAgent":
    "The 安全设计工作台 agent can read, edit, and use this file as project context.",
  "designFiles.documentTemplate.capabilityImages":
    "Paste images, or drag image files onto the editor; uploaded images are inserted at the cursor.",
  "designFiles.documentTemplate.scenarioHeading": "Scenario guide",
  "designFiles.documentTemplate.scenario.prototype":
    "For prototypes, outline the product goal, target users, flows, screens, modules, interaction states, responsive breakpoints, and design tokens such as color, type, spacing, radius, and motion.",
  "designFiles.documentTemplate.scenario.wireframe":
    "For wireframes, describe the user flow, screen list, layout hierarchy, content blocks, low-fidelity constraints, and the questions the structure should answer before visual design.",
  "designFiles.documentTemplate.scenario.mobile":
    "For mobile apps, list target platforms, screens, navigation model, gestures, native patterns, device sizes, states, and mobile design tokens.",
  "designFiles.documentTemplate.scenario.slideDeck":
    "For slides, write a paginated PPT outline: one section per slide with title, purpose, key message, evidence, visual direction, speaker notes, and export needs.",
  "designFiles.documentTemplate.scenario.document":
    "For documents, define audience, tone, section structure, source material, citations or data, layout expectations, and PDF/export requirements.",
  "designFiles.documentTemplate.scenario.image":
    "For images, specify subject, aspect ratio, composition, visual style, brand tokens, reference files, and negative constraints.",
  "designFiles.documentTemplate.scenario.video":
    "For video, draft a storyboard with scenes, timing, captions, motion, assets, audio notes, and output format.",
  "designFiles.documentTemplate.scenario.hyperframes":
    "For HyperFrames, describe the HTML motion piece: scenes, timeline, captions, audio-reactive moments, transitions, and capture/export requirements.",
  "designFiles.documentTemplate.scenario.audio":
    "For audio, define voice or music direction, duration, mood, script or copy, pacing, pronunciation notes, and final use.",
  "designFiles.documentTemplate.scenario.liveArtifact":
    "For live artifacts, describe data sources, refresh cadence, widgets, filters, interactions, empty/loading/error states, and any alerts or automations.",
  "designFiles.documentTemplate.scenario.designSystem":
    "For design systems, list brand goals, tokens, typography, color, spacing, components, assets, references, and rules to follow or avoid.",
  "designFiles.documentTemplate.scenario.default":
    "Describe the audience, deliverable, required content, references, constraints, and what done should look like.",
  "designFiles.documentTemplate.nextHeading": "Next step",
  "designFiles.documentTemplate.nextBody":
    "Review and edit this document, then ask 安全设计工作台 to generate, revise, or operate from it.",

