  "home.example.web-clone.1": "Website URL to clone: https://example.com",
  "home.example.prototype.1": "Design a high-converting website for an AI CRM with a clear hero, feature story, proof points, and trial CTA",
  "home.example.prototype.2": "Create a desktop dashboard for a team knowledge base with search, recent updates, permissions, and collaboration entry points",
  "home.example.prototype.3": "Redesign onboarding for a financial SaaS product so new users can connect data, finish setup, and see first value fast",
  "home.example.prototype.4": "Prototype a mobile fitness coaching app covering goal setup, weekly plans, workout check-ins, and progress review",
  "home.example.deck.1": "Research the market opportunity for a product launch, including competitors, target users, pricing hypotheses, and launch narrative",
  "home.example.deck.2": "Generate a weekly team status report with progress, risks, metric changes, and next-week priorities",
  "home.example.deck.3": "Design an investor pitch with market sizing, growth model, product advantage, and three-year forecast data",
  "home.example.deck.4": "Create a strategic business review deck covering quarterly performance, root causes, opportunities, and next actions",
  "home.example.image.1": "Generate a glassmorphism AI workspace poster with multi-screen collaboration, soft lighting, and a premium launch mood",
  "home.example.image.2": "Create an ecommerce hero image for new wireless headphones that highlights material detail, lifestyle context, and core benefits",
  "home.example.image.3": "Design a minimalist tech launch key visual with a clean composition, strong product focus, and restrained launch copy",
  "home.example.image.4": "Make a social teaser set for a product drop, including countdown, close-up detail, benefit reveal, and launch-day visual",
  "home.example.video.1": "Make an 8-second product reveal film that moves from silhouette to close-up detail and ends on the brand mark",
  "home.example.video.2": "Generate an app feature demo video that follows the user journey, key states, and final outcome",
  "home.example.video.3": "Create a vertical brand opener with rhythmic typography, product close-ups, and a clean logo ending for short-form video",
  "home.example.video.4": "Turn a website into a 15-second social ad by extracting the hero claim, interaction highlights, and a clear CTA",
  "home.example.hyperframes.1": "Build a captioned product launch short with title cards, feature shots, rhythmic transitions, and an ending CTA",
  "home.example.hyperframes.2": "Generate an audio-reactive data visualization where bars, particles, and titles respond to narration beats",
  "home.example.hyperframes.3": "Create a 3-second logo outro using line convergence, subtle elasticity, and the brand color system",
  "home.example.hyperframes.4": "Make an animated flight-route map showing city nodes, route growth, mileage data, and a final summary frame",
  "home.example.audio.1": "Generate a product startup sound that feels light, trustworthy, slightly futuristic, and suitable for a desktop app launch",
  "home.example.audio.2": "Create a 20-second podcast intro bed with a warm opening, clear pulse, and a clean handoff into voiceover",
  "home.example.audio.3": "Make a seamless ambient loop for a meditation app using soft nature textures, low-frequency warmth, and calm pacing",
  "home.example.audio.4": "Generate a branded notification sound set for success, reminder, and error states while keeping one sonic identity",
