  "community.prompt.image": "Create an image about “[insert image subject]” using the “{title}” template.\n\nPurpose\n[Where the image will be used and the single message it must communicate]\n\nSubject\n[Main subject, people, product, objects, and details that must remain accurate]\n\nScene and composition\n[Environment, shot size, viewpoint, subject placement, and negative space]\n\nStyle and mood\nKeep the template's visual language, color relationships, and material feel while adapting the content to the new subject. Do not copy the example elements literally.\n\nExact text\n[Text that must appear in the image, or “no text”]\n\nOutput\n[Aspect ratio, dimensions, quality, and destination platform]\n\nAvoid\nDo not add unprovided logos, invented copy, watermarks, or irrelevant decoration.",
  "community.prompt.motion": "Create a motion piece about “[insert subject]” using the “{title}” template.\n\nCommunication goal\n[Message and usage context]\n\nRequired content\n[Exact copy, brand elements, product, and supplied assets]\n\nPacing and shots\n[Duration, aspect ratio, rhythm, key transitions, and end state]\n\nDesign direction\nKeep the template's visual language and motion behavior while restructuring it around the real content. Do not copy the example copy.\n\nOutput\n[Dimensions, frame rate, format, looping behavior, and transparency needs]",
  "community.prompt.deliverable.slides": "a complete slide deck",
  "community.prompt.deliverable.page": "a production-ready web page",
  "community.prompt.document": "Create {deliverable} about “[insert topic, product, or project name]” using the “{title}” template.\n\nUsage context\n[Presentation, proposal, website, campaign, or another concrete scenario]\n\nAudience\n[Audience roles and the questions they care about most]\n\nPrimary outcome\n[What the audience should understand, believe, or do afterwards]\n\nCore content\n1. [Essential conclusion]\n2. [Facts, data, or features that support it]\n3. [Cases, flows, or selling points that need emphasis]\n\nAvailable material\n[Paste real copy, data, image links, and references. Mark missing information explicitly; do not invent it.]\n\nDesign direction\nKeep the template's visual language, layout rhythm, and interaction character while rebuilding the hierarchy around the real content. Do not copy the example copy or use Lorem ipsum.\n\nDelivery requirements\n[Page/slide scope, dimensions, device support, file format, and deadline]",
