  "next.prompt.projectContinue": "Continue from the stopped or incomplete turn. Read the conversation, current project files, and any visible errors, then take the next concrete step. If a primary artifact already exists, update it in place; otherwise create the missing primary artifact and summarize what changed.",
  "next.prompt.projectGenerate": "Generate the missing project artifact now. Use the current conversation and project context to create the primary previewable deliverable. Save it with a short semantic filename derived from the request, such as investor-pitch-deck.html, refund-dashboard.html, or pricing-page.html; use index.html only for a fixed runtime convention or a launcher/overview. Save it into this project and include a concise summary of the files created.",
  "next.prompt.designSystemRefine": "Use AI extraction to refine this design system in place. Read the current DESIGN.md, brand.json, source context, tokens, typography, palette, assets, and component kit previews. Re-measure any linked website or source files when available, then update the same design system id without creating a duplicate. Focus on stronger token roles, brand voice, component guidance, light/dark kit quality, and reusable implementation notes. Finish by summarizing what changed and which files were updated.",
  "next.prompt.designSystemAudit": "Audit this design system for readiness. Check DESIGN.md, brand.json, variables.css, theme.json, kit.html, kit.dark.html, generated artifacts, palette contrast, typography specimens, spacing/radius rules, and component coverage. Fix the highest-impact issues directly, keep the same registered design system id, and report remaining gaps before publishing or using it in other projects.",
